  function setupNames(){const used=new Set(setupPlayers.map(p=>p.pawnId));$('playerCountLabel').textContent=`${setupPlayers.length} of 10`;$('addPlayerBtn').disabled=setupPlayers.length>=10;$('nameFields').innerHTML=setupPlayers.map((row,i)=>{const chosen=PAWNS.find(p=>p.id===row.pawnId)||PAWNS[i];return`<div class="name-entry" data-player="${i}"><div class="player-setup-title"><span class="mini-sign pawn-preview" style="background:${chosen.color};color:${pawnText(chosen)}">STOP</span><strong>Player ${i+1} · ${chosen.label}</strong><button class="remove-player ghost" type="button" data-remove="${i}" ${setupPlayers.length<=2?'disabled':''} aria-label="Remove player ${i+1}">Remove</button></div><label>Name or nickname <input class="name-main" maxlength="28" aria-label="Player ${i+1} name or nickname" value="${escapeHTML(row.name)}" required></label><div class="color-picker" role="group" aria-label="Player ${i+1} pawn color">${PAWNS.map(p=>`<button type="button" class="color-option ${p.id===row.pawnId?'selected':''}" data-color="${p.id}" data-player="${i}" ${used.has(p.id)&&p.id!==row.pawnId?'disabled':''} aria-pressed="${p.id===row.pawnId}" title="${p.label}"><span class="mini-sign" style="background:${p.color};color:${pawnText(p)}">STOP</span><span>${p.label}</span></button>`).join('')}</div></div>`}).join('')}
  function boardCoords(event){const svg=$('boardOverlay'),matrix=svg.getScreenCTM();if(!matrix)return null;const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;return point.matrixTransform(matrix.inverse())}
  function onPointerDown(event){if(state?.paused)return;const pawn=event.target.closest?.('.pawn-outer');if(!pawn||!state||state.settings.movement!=='drag'||Number(pawn.dataset.person)!==state.active||!['roll','drag'].includes(state.phase))return;const point=boardCoords(event);if(!point)return;drag={pointer:event.pointerId,startPhase:state.phase,index:state.active,point};$('boardOverlay').setPointerCapture?.(event.pointerId);pawn.classList.add('pawn-ghost');event.preventDefault()}
